'QZ_Step_Install' => '1. このコンピューターにQZ Trayをインストールします。qz.ioから無料でダウンロードし、起動したままにしてください（Windowsではシステムトレイ、macOSではメニューバーに常駐します）。',
'QZ_Step_Connect' => '2. ラベルプリンターをUSBで接続し、OSにインストールされていることを確認します（Windows：設定 > プリンターとスキャナー — macOS：システム設定 > プリンタとスキャナ）。',
'QZ_Step_Detect' => '3. 上の「プリンター名」の横にある⟳ボタンをクリックしてこのコンピューターのプリンターを検出し、ラベルプリンターを選択します。空欄の場合はコンピューターの既定のプリンターを使用します。',
'QZ_Step_Cert' => '4. 許可ポップアップなしで印刷するには、下の証明書をダウンロードし、override.crt という名前に変更してQZ Trayのインストールフォルダーにコピーします（Windows：C:\\Program Files\\QZ Tray — macOS：/Applications/QZ Tray.app/Contents/Resources — Linux：/opt/qz-tray）。その後、QZ Trayを終了して再起動します。',
'QZ_Step_Test' => '5. 下の「テストラベルを印刷」をクリックします。QZ Trayから許可を求められたら「許可」をクリックしてください。証明書をインストール済みであれば、再度確認されることはありません。',
'QZ_Step_Save' => '6. 「送信」をクリックしてこの設定を保存します。以降、バーコード印刷ページのラベルはブラウザの印刷ダイアログなしでこのプリンターに直接印刷されます。',
'QZ_Setup_Note' => 'QZ Trayは閲覧に使用しているコンピューター上で動作するため、Stockyがリモートサーバーでホストされていても機能します。ラベルを印刷するすべてのコンピューターにQZ Trayのインストールが必要です。',

