'Upd_Guide_Run_Upload' => '{upload}：ダウンロードしたパッケージをアップロード欄にクリックまたはドラッグします。大きなファイルは小さなチャンクに分けてアップロードされるため、アップロード上限の低い共有ホスティングでも動作します。チェックサムにより、破損や不完全なアップロードを防ぎます。',
'Upd_Upload_The_Zip' => 'ZIP をアップロード',
'Upd_Guide_Run_Validation' => 'アップロード後、{auto}（{button} ボタンで再実行できます）。システムは次の項目をチェックします：ZIP の整合性、パッケージの構造と完全性、バージョンの互換性（ダウングレードは拒否されます）、必要な PHP バージョンと拡張機能、ファイルの権限、ディスクの空き容量、データベース接続、設定、および他の更新が実行中でないこと。',
'Upd_Validation_Runs_Automatically' => '検証が自動的に実行されます',
