'Woo_Stock_Not_Live' => '在庫リアルタイムなし',
'Woo_Guide_Realtime_Lead' => '一方向のみ：ERP から送信される在庫と商品です。WooCommerce で行われた注文や商品の編集は、引き続きスケジュールに従って届きます。もう一方のタブを参照してください。',
'Woo_Push_Stock_On_Change' => '在庫の変更時に即座に送信',
'Woo_Setting_People_Miss' => '見落とされがちな設定です',
