'Woo_Does_Not' => 'されません',
'Woo_Guide_Tick_Instant' => '{settings} タブで {option} にチェックを入れてください。設定はそれだけです。ワーカーも cron も不要です。以後、販売、返品、在庫調整、移動、仕入の受け入れのたびに、販売の保存直後に該当商品のみを送信します。20行の販売でも送信は20回ではなく1回です。レジが待たされることはありません。',
'Woo_Currently' => '現在：',
'Woo_Instant_On_Text' => 'オン — 変更時に在庫を送信',
'Woo_Instant_Off_Text' => 'オフ — 在庫はスケジュールのみ',
'Woo_Guide_Instant_Note' => '送信されるのは、すでに WooCommerce と連携済みの商品のみです。一度も同期されていない商品は、ショップ側に修正対象がありません。バリエーション商品は親商品を通じて送信され、コンボ商品は構成品のいずれかが動くと再送信されます。一括操作（商品の削除、倉庫のリセット）はイベントを発生させずに在庫を書き込むため、1時間ごとの在庫同期も併用することをお勧めします。',
'Woo_Push_Products_On_Save' => '商品の保存時に即座に送信',
'Woo_Guide_Tick_Auto_Products' => '{settings} タブで {option} にチェックを入れると、Stocky で作成・編集・複製された商品は保存直後に WooCommerce に送信されます（詳細、価格、バリエーション、画像、その後に在庫）。新しい商品は夜間の商品同期を待たずに、すぐにショップに作成されます。',
'Woo_On' => 'オン',
'Woo_Off' => 'オフ',
'Woo_Guide_Bulk_Imports_Note' => '一括インポートは1件ずつ送信されません。インポート後に商品同期を実行してください。送信した商品が正しいカテゴリに入るよう、先にカテゴリとブランドを同期してください。',
'Woo_Nothing_Else_To_Install' => '追加のインストールは不要',
'Woo_Guide_Same_Process' => 'キューワーカーも cron エントリも不要です。送信は、販売を処理したのと同じプロセスで、応答を返した{after}に実行されるため、レジが WooCommerce を待つことはありません。送信が重なることはなく、送信中に行われた変更はその完了を待ってから直後に送信されます。',
'Woo_After' => '後',
'Woo_Guide_Shop_Stops_Answering' => '応答しなくなったショップは8秒で打ち切られ、販売のたびに再び待たされないよう、送信は5分間一時停止します。その間に発生した変更は一時停止後の最初の送信で送られ、いずれにせよ1時間ごとの在庫同期で追いつきます。一時停止はすべてログタブに記録されます。',
'Woo_Guide_Artisan_Exception' => '例外が1つあります：artisan コマンドによる在庫変更には後続する応答がないため、代わりに {queue} キューに入れられます。これらも速やかに送信するには、そのキューを処理してください：',
