'Woo_Guide_Not_Woo_Queue' => '意図的に {queue} キューは使用していません。そのキューは数時間かかるカタログのバッチを処理しており、その後ろに並んだ即時送信は即時ではなくなるためです。',
'Woo_On_A_Schedule' => 'スケジュール',
