'Woo_Commands_Worth_Knowing' => '知っておくと便利なコマンド',
'Woo_Worth_Knowing' => '知っておくべきこと',
'Woo_Guide_Changing_Url_Clears' => 'ストア URL または API キーを変更すると、すべてのマッピングがクリアされます。商品、カテゴリ、ブランド、顧客はすべて新しいストアに再同期されます。',
'Woo_Guide_Keep_Skus' => 'Stocky と WooCommerce の間で SKU を一致させてください。それが重複を防ぎ、安全な再連携を可能にします。',
