'Xero_Guide_5' => '勘定コードを確認します：売上勘定には請求書明細が計上されます。支払済みの販売で支払いも記録する場合は、銀行口座の勘定コードを設定してください。',
'Xero_Guide_6' => 'まず顧客を送信し、次に請求書を送信します。請求書番号は販売の参照番号であるため、リンクをリセットしても重複は Xero によって拒否されます。',
'Xero_Amounts_Title' => '金額は税込のままそのまま送信されます',
'Xero_Amounts_Desc' => '請求書は販売を正確に反映する NoTax 明細を使用するため（商品 + 配送 − 割引 + 税）、Xero の合計は常に Stocky の合計と一致します。税と配送の明細は、会計担当者が Xero 内で適切な勘定に振り替えることができます。',
'Xero_Org_Connected' => 'Xero 組織に接続しました。',
'Jumia_Hero_Title' => 'Jumia マーケットプレイス同期',
