'Jumia_Push_Prices_Stock_Title' => '価格と在庫を Jumia へ送信',
'Jumia_Push_Prices_Stock_Desc' => 'Jumia の出品の {sku} と一致する SKU を持つすべての商品（およびバリエーション）の現在の価格と数量を送信します。更新は Seller Center のフィードとして送信され、非同期で適用されます — フィード ID はログタブに記録され、項目ごとの却下は Seller Center のフィードステータス画面に表示されます。',
'Jumia_Push_Prices_Stock' => '価格と在庫を送信',
'Jumia_Pull_Orders_Desc' => 'マーケットプレイスの注文を販売として取り込み（参照番号は {ref} のような形式）、Seller SKU で商品と照合します。取り込み済みおよびキャンセル済みの注文はスキップされるため、定期的に取り込んでも安全です。支払いは配達済みの注文のみ支払済みとしてマークされます（Jumia は代金引換が主流のため）。',
'Jumia_Guide_1' => 'Jumia の {sellerCenter} で {menu} を開き、API キーを生成します。',
'Jumia_Guide_2' => 'お住まいの国の API URL（例：ナイジェリアは {ng}、ケニアは {ke}、エジプトは {eg}）、Seller Center アカウントのメールアドレス、キーを入力し、{test} を実行します。',
'Jumia_Guide_3' => '各 Jumia 出品の {sku} が Stocky の商品コードと一致していることを確認してください — これが在庫送信と注文照合の両方で使用される識別子です。',
'Jumia_Guide_4' => '在庫が変わったら価格と在庫を送信し、定期的に注文を取り込みます（この API では Jumia に Webhook はありません）。',
'Jumia_Guide_5' => '新規出品の作成は Seller Center で行います — Jumia ではカテゴリ固有の属性と画像審査が必要で、これらは同社のポータルでなければうまく処理できません。',
