'Shopify_G_Manual_Desc' => '{centre} から開始した同期はすぐに応答し、バックグラウンドで実行されます。短い区切りごとに、前回停止した位置から処理を続行します。長時間の Web リクエストを打ち切るホスティング（LiteSpeed、nginx、ロードバランサー）でも大きなカタログが途中で切れることはなく、ページを閉じても停止しません。そのためのワーカーは cron の行をもう 1 つ追加するだけです：',
