'Shopify_G_Cron_Entry' => 'cronエントリ',
'Shopify_G_Cron_Entry_Desc' => 'これがないとスケジュール処理は一切実行されません。このモジュール専用の1行です。他にスケジュール設定しているものと並べて追加してください:',
'Shopify_G_Cron_Note' => 'ステップの最短間隔が5分であるため、プランで使える最小の単位は5分ごとです。より粗いエントリにすると、それが下限になります。たとえば{example}の場合、5分に設定したステップは15分ごとに実行されます。Windowsではタスクスケジューラを使用し、プログラム{program}、引数{args}、開始フォルダー{dir}を指定してください。',
'Shopify_G_Switch_On_Plan' => 'スイッチをオンにしてプランを選択',
'Shopify_G_Plan_Desc' => '{where} スイッチはcronが動作できるかどうかを決め、プランは何を実行するかを決めます。{step}とは、1つのエンティティを1方向に処理するもので、それぞれ独自の間隔を持ちます（{first}、{second}）。自身の入力欄が空のステップには既定の間隔が使用されます。',
'Shopify_G_Step_Lower' => 'ステップ',
'Shopify_G_Plan_Note' => 'プランを空のままにすると、ストアは既定の間隔で注文を取り込み、在庫をプッシュします。ほとんどのショップにはこれで十分です。注文は取り込みのみです。顧客が注文するのはShopify側だからです。',
'Shopify_G_Schedule_On' => 'スケジュール オン',
'Shopify_G_Schedule_Off' => 'スケジュール オフ — 手動のみ',
'Shopify_G_When_Step_Runs' => 'ステップが実際に実行されるタイミング',
'Shopify_G_When_Note' => 'ステップは、同じステップが最後に{started}されてから間隔以上の時間が経過したときに実行対象となります（実行履歴から判断）。そのため、手動で開始した同期は次の自動同期を後ろにずらし、失敗し続けるステップは毎回ではなく設定した間隔で再試行されます。ストアの概要には、各ステップの最終実行、次回予定時刻、ブロックされている場合はその理由が表示されます。最初のカタログプッシュは、スケジュールに組み込む前に手動で（まず{dryRun}で）実行してください。',
'Shopify_G_Started_Lower' => '開始',
