'Shopify_G_Product_Images' => '商品画像',
'Shopify_G_Img_1' => '画像は{push}時に商品と一緒に送信されます。メイン画像、ギャラリー、独自の画像を持つバリエーションごとに1枚の順で、最大50枚までです。',
'Shopify_G_Products_Push' => '商品プッシュ',
'Shopify_G_Img_2' => 'バリエーションの画像は商品と一緒にアップロードされ、その後{assigned}。これはShopifyの仕組みによるもので、バリエーションは商品画像の1つを参照します。メイン画像を流用するバリエーションでは、画像が二重にアップロードされることはありません。',
