'Cr_Guide_S_cancelled' => '出荷手配はキャンセルされました。',
'Cr_Guide_T_Booking' => '注文の出荷手配',
'Cr_Guide_B_Booking' => '「配送業者に送信」では、販売の情報（受取人、住所、代引き金額としての未払額、商品の重量）がフォームに自動入力されます。独自の市区町村リストを持つ配送業者では選択欄が表示され、選択内容はその市区町村について記憶されます。アグリゲーター、DHL、FedEx、UPS、Lalamove では「料金を比較」が利用でき、料金を選んで「手配」で購入します。販売一覧から複数の販売をまとめて出荷手配することもできます。',
'Cr_Guide_T_Cod' => '代金引換',
'Cr_Guide_B_Cod' => '代引きの荷物は「未回収」から「配送業者が回収済み」（配達時）、「入金済み」へと進みます。入金を報告する配送業者では最後のステップが自動で進みます。それ以外の配送業者では「代引きを更新」を使用してください。配送業者設定で口座を選択している場合、入金は販売の支払いとして記録されます。荷物の配送が完了すると、配送料金を経費として保存できます。',
'Cr_Guide_T_Returns' => '返送された荷物',
'Cr_Guide_B_Returns' => 'デフォルトでは、返送された荷物は配送業者出荷の「確認待ちの返送品」で待機します。「再入庫」では注文全体の販売返品を作成し、商品を在庫に戻します。「却下」では何も在庫に戻しません（破損・紛失した荷物向け）。配送業者設定で自動再入庫に切り替えることもできます。',
'Cr_Guide_T_Customers' => '顧客へのメッセージと追跡ページ',
'Cr_Guide_B_Customers' => '配送業者設定の顧客通知では、チェックを入れたステータスで、独自の文面による SMS、メール、または WhatsApp を荷物ごとに1回ずつ送信します。オンラインストアの追跡ページでは、顧客が追跡番号、または注文番号と電話番号で荷物の状況を確認できます。返送の多い顧客には、出荷手配時に返品リスクのバッジが表示されます。',
'Cr_Guide_T_Labels' => 'ラベル',
'Cr_Guide_B_Labels' => '「ラベルを印刷」では、配送業者が独自のラベル（PDF、リンク、または画像）を発行する場合はそのラベルを、それ以外の場合は追跡バーコードと回収金額を記載した Stocky のラベルを出力します。印刷するには、このサイトのポップアップを許可してください。DHL、FedEx、UPS は出荷手配時に一度だけラベルを発行するため、Stocky が再印刷用に保存します。',
'Cr_Guide_T_Faq' => 'トラブルシューティング',
'Cr_Guide_Q_Test' => '接続テストが失敗する',
'Cr_Guide_A_Test' => 'テストモードのキーはテストモードで、本番キーは本番モードで使用します。両者は異なります。正確な原因は、配送業者ログを開いて配送業者の応答を確認してください。',
'Cr_Guide_Q_City' => '配送業者が市区町村または住所を受け付けない',
'Cr_Guide_A_City' => '出荷手配フォームで配送業者の市区町村リストから選択してください。配送業者は独自の名称のみを受け付けます。郵送先住所を使用する配送業者では、都道府県・州、郵便番号、2文字の国コードも必要です。',
'Cr_Guide_Q_Webhook' => 'ステータスが自動で変わらない',
'Cr_Guide_A_Webhook' => '更新をプッシュする配送業者の場合、Webhook URL が配送業者側に登録されているか確認してください。配送業者ログには受信したすべての更新、または拒否された理由（シークレットの誤りなど）が表示されます。その他の配送業者は配送業者設定のスケジュールに従って確認され、「今すぐステータスを確認」で即時に問い合わせることができます。',
'Cr_Guide_Q_Stuck' => '出荷にステータス確認エラーが表示される',
'Cr_Guide_A_Stuck' => '配送業者が直近の確認を拒否しました。理由は出荷画面と配送業者ログに表示されます。失敗が繰り返されると、その出荷は自動確認の対象外になります。原因を解消してから「今すぐステータスを確認」を使用してください。',
